  if(fx<0||fz<0||fx>GROUND_NX||fz>GROUND_NZ) return height(x,z);
  var ix=Math.min(GROUND_NX-1,Math.floor(fx)), iz=Math.min(GROUND_NZ-1,Math.floor(fz)), u=fx-ix, v=fz-iz;
